import java.io.InputStream;
import java.io.IOException;

public class Main {

    static class FastIO {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastIO(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            byte c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return neg ? -res : res;
        }
    }

    static class FenwickTree {
        int n;
        long[] tree;

        public FenwickTree(int n) {
            this.n = n;
            this.tree = new long[n + 2];
        }

        public void add(int i, long delta) {
            for (; i <= n; i += i & -i) {
                tree[i] += delta;
            }
        }

        public long query(int i) {
            long sum = 0;
            for (; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }

        public void rangeAdd(int l, int r, long delta) {
            if (l > r) return;
            add(l, delta);
            add(r + 1, -delta);
        }
    }

    public static void main(String[] args) throws IOException {
        FastIO in = new FastIO(System.in);
        int n = in.nextInt();
        if (n == -1) return;
        int m = in.nextInt();

        FenwickTree bitA = new FenwickTree(n);
        FenwickTree bitB = new FenwickTree(n);

        StringBuilder out = new StringBuilder();

        for (int k = 0; k < m; k++) {
            int type = in.nextInt();
            if (type == 1) {
                long i = in.nextInt();
                long v = in.nextInt();
                int l = (int) i;
                int r = (int) Math.min((long) n, i + v - 1);
                long a = v + i;
                long b = -1;
                bitA.rangeAdd(l, r, a);
                bitB.rangeAdd(l, r, b);
            } else if (type == 2) {
                long i = in.nextInt();
                long v = in.nextInt();
                int l = (int) Math.max(1L, i - v + 1);
                int r = (int) i;
                long a = v - i;
                long b = 1;
                bitA.rangeAdd(l, r, a);
                bitB.rangeAdd(l, r, b);
            } else {
                int i = in.nextInt();
                long ans = bitA.query(i) + bitB.query(i) * i;
                out.append(ans).append('\n');
            }
        }

        System.out.print(out);
    }
}
